from __future__ import annotations
import argparse,csv,hashlib,io,json
from pathlib import Path
from typing import Any
R=Path(__file__).resolve().parents[2]; S=R/'paper/reproducibility/core_tables_spec.json'; D=R/'paper/tables'; M=D/'core_tables_manifest.json'
IDS={'model_workflow_coverage','official_demo_parity','fitting_statistics_classification','recovery_model_selection','backend_gpu_applicability','release_reproducibility_provenance'}
def h(b:bytes)->str:return hashlib.sha256(b).hexdigest()
def hf(p:Path)->str:return h(p.read_bytes())
def j(p:Path)->Any:
 if not p.is_file():raise FileNotFoundError(f'Required evidence file is missing: {p.relative_to(R)}')
 return json.loads(p.read_text(encoding='utf-8'))
def d(x:Any)->str:
 if x is None:return '—'
 if isinstance(x,bool):return str(x).lower()
 if isinstance(x,float):return repr(x)
 if isinstance(x,list):return '[]' if not x else ', '.join(map(d,x))
 return str(x)
def sources(spec):
 out={}; prov={}
 for a,m in spec['sources'].items():
  p=R/m['path']; x=j(p); actual=hf(p)
  if actual!=m['sha256']:raise RuntimeError(f"Frozen evidence hash mismatch for {m['path']}: expected {m['sha256']}, got {actual}")
  out[a]=x; prov[a]={'path':m['path'],'sha256':actual}
 return out,prov
def md(title,cols,rows):
 esc=lambda x:x.replace('|','\\|').replace('\n',' ')
 z=['<!-- Generated by paper/scripts/generate_core_tables.py; do not edit manually. -->',f'# {title}','','| '+' | '.join(map(esc,cols))+' |','| '+' | '.join('---' for _ in cols)+' |']
 z+=['| '+' | '.join(map(esc,r))+' |' for r in rows];return '\n'.join(z)+'\n'
def cv(cols,rows):
 q=io.StringIO(newline='');w=csv.writer(q,lineterminator='\n');w.writerow(cols);w.writerows(rows);return q.getvalue()
