 r=[[p['case_id'],p['classification'],d(p['matlab']['hgf_binary']['success']),d(p['hgfx']['hgf_binary']['success']),d(p['matlab']['ehgf_binary']['success']),d(p['hgfx']['ehgf_binary']['success']),d(p['mismatches']),f"run {a['model_selection']['workflow_run']}; artifact {a['model_selection']['artifact_id']}",a['model_selection']['classification_file']],[u['case_id'],u['classification'],d(u['matlab']['uhgf_binary']['success']),d(u['hgfx']['uhgf_binary']['success']),d(u['matlab']['uhgf_ar1_binary']['success']),d(u['hgfx']['uhgf_ar1_binary']['success']),d(u['mismatches']),f"run {a['uhgf_ar1']['workflow_run']}; artifact {a['uhgf_ar1']['artifact_id']}",a['uhgf_ar1']['classification_file']]];return c,r
